CREATE OR REPLACE FUNCTION public.guard_assignments_no_deleted_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        begin
          perform pg_advisory_xact_lock(54002010, 31);
          if not exists(select 1 from personnel p where p.id=new.person_id and p.data_status='active' and p.employment_status not in ('离职','停职')) then raise exception '人员已删除、人员不存在或身份对应不一致，不能新增关联'; end if;
          return new;
        end $function$

